window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[80]={"id":"080","numero":80,"titre":"Dopage et conduites dopantes","objectifs":[{"id":"80-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du dopage et des conduites dopantes","contenu":"<p>Le <strong><span class=\"kw-def\">dopage</span></strong> et <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">conduites dopantes</span></strong> sont deux notions distinctes : la seconde est <strong>large</strong>, la première en est le <strong>sous-ensemble réglementé</strong>, restreint au sportif en compétition.</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Conduites dopantes</span></strong></td>\n            <td>Utilisation <strong>intentionnelle</strong> de produits et de méthodes de modification de certaines compétences de la personne, afin d'<strong>affronter un obstacle</strong> (réel ou ressenti) et/ou d'<span class=\"kw-clinique\">améliorer ses performances</span> — qu'elles soient <strong>physiques, intellectuelles ou artistiques</strong>. Notion large, qui <strong>ne se limite pas au sport</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Dopage</span></strong></td>\n            <td>Ne concerne <strong>que <span class=\"kw-clinique\">les</span> sportifs</strong> qui, dans le cadre de <strong>compétitions ou de manifestations organisées par les fédérations</strong>, utilisent des <span class=\"kw-ttt\">substances</span> ou des <span class=\"kw-ttt\">méthodes</span> inscrites sur une liste mise à jour <strong>chaque année</strong> par l'<strong><span class=\"kw-def\">Agence mondiale antidopage (AMA)</span></strong>. Ces substances et méthodes visent à <span class=\"kw-clinique\">augmenter les capacités physiques ou mentales</span> du sportif.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-def\">dopage</span> est le versant <strong>sportif et réglementé</strong> des conduites dopantes. L'<strong><span class=\"kw-def\">AFLD</span></strong> (Agence française de lutte contre le dopage) met à disposition un <strong>moteur de recherche</strong> permettant de vérifier si un médicament contient une substance <span class=\"kw-ci\">interdite</span>.</div>","frequence":0},{"id":"80-2","rang":"A","rubrique":"Définition","titre":"Savoir comment un produit est qualifié de dopant, comment une méthode est qualifiée de dopante","contenu":"<p>Une <span class=\"kw-ttt\">substance</span> ou une <span class=\"kw-ttt\">méthode</span> est qualifiée de <strong><span class=\"kw-def\">dopante</span></strong> par son <strong>inscription sur la liste des interdictions</strong>, établie et <strong>mise à jour chaque année</strong> par l'<strong><span class=\"kw-def\">AMA</span></strong> (Agence mondiale antidopage).</p>\n      <h4>Catégories d'interdiction</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Périmètre d'interdiction</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Substances S0 à S5</strong></td><td>Interdites <strong>en compétition et hors compétition</strong></td></tr>\n          <tr><td><strong>Substances S6 à S9</strong></td><td>Interdites <strong>en compétition uniquement</strong></td></tr>\n          <tr><td><strong>Substances P1</strong></td><td>Interdites <strong>dans certains sports</strong> seulement</td></tr>\n          <tr><td><strong>Méthodes</strong></td><td>Toutes interdites <strong>en compétition et hors compétition</strong></td></tr>\n        </tbody>\n      </table>\n      <p>Le détail des classes S0 à P1 et des méthodes est traité dans l'objectif suivant.</p>\n      <div class=\"callout callout-warn\"><strong>Exception thérapeutique.</strong> La procédure d'<strong><span class=\"kw-def\">autorisation d'usage à des fins thérapeutiques (AUT)</span></strong> permet à un sportif de suivre un traitement contenant une <span class=\"kw-ttt\">substance interdite</span>, pour un <strong>état pathologique diagnostiqué</strong> — aigu ou chronique.</div>\n      <div class=\"callout callout-info\"><strong>En pratique.</strong> L'<span class=\"kw-def\">AFLD</span> propose un <strong>moteur de recherche</strong> en ligne pour vérifier le statut (autorisé / <span class=\"kw-ci\">interdit</span>) d'un médicament.</div>","frequence":0},{"id":"80-3","rang":"B","rubrique":"Définition","titre":"Connaître les principales substances et méthodes dopantes","contenu":"<p>La liste des interdictions de l'<span class=\"kw-def\">AMA</span> distingue <span class=\"kw-clinique\">les</span> <strong>substances</strong> (classes <span class=\"kw-ttt\">S0 à S9</span> et <span class=\"kw-ttt\">P1</span>) et les <strong>méthodes</strong>. Listes de molécules non exhaustives.</p>\n      <h4>Substances interdites en compétition et hors compétition</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Exemples</th><th>Effet recherché</th></tr></thead>\n        <tbody>\n          <tr><td><strong>S0</strong> — Substances non approuvées</td><td>Toute substance pharmacologique <strong>non approuvée</strong> pour un usage thérapeutique humain (ex. molécules en développement pré-clinique ou clinique)</td><td>—</td></tr>\n          <tr><td><strong>S1</strong> — Agents anabolisants</td><td><span class=\"kw-ttt\">Stéroïdes anabolisants androgènes</span> ; autres agents anabolisants</td><td><span class=\"kw-clinique\">↑ masse musculaire</span> ; ↑ performance et résistance à la fatigue</td></tr>\n          <tr><td><strong>S2</strong> — Hormones peptidiques, facteurs de croissance</td><td><span class=\"kw-ttt\">EPO</span> (érythropoïétine) et agents stimulant l'érythropoïèse ; <span class=\"kw-ttt\">GH</span> (hormone de croissance)</td><td><strong>EPO :</strong> <span class=\"kw-clinique\">↑ transport de l'O₂</span> et endurance<br><strong>GH :</strong> <span class=\"kw-clinique\">↑ masse musculaire</span></td></tr>\n          <tr><td><strong>S3</strong> — β2-agonistes</td><td>Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">β2-agonistes</span> — <strong>sauf <span class=\"kw-ttt\">salbutamol</span>, formotérol et salmétérol inhalés</strong> sous un certain <span class=\"kw-chiffre\">seuil</span></td><td><span class=\"kw-clinique\">↑ fonction respiratoire</span> ; ↑ capacité d'effort et de résistance</td></tr>\n          <tr><td><strong>S4</strong> — Modulateurs hormonaux et métaboliques</td><td><span class=\"kw-ttt\">Inhibiteurs d'aromatase</span> ; modulateurs sélectifs des récepteurs aux œstrogènes ; modulateurs métaboliques</td><td>↑ <span class=\"kw-clinique\">masse</span> musculaire ; masquage des EI d'un mésusage d'<span class=\"kw-ttt\">anabolisants</span></td></tr>\n          <tr><td><strong>S5</strong> — <span class=\"kw-ttt\">Diurétiques</span> et agents masquants</td><td><span class=\"kw-ttt\">Diurétiques</span> ; agents masquants</td><td>Aide à la <span class=\"kw-clinique\">perte de poids</span> ; <strong>masquage</strong> d'autres produits dopants</td></tr>\n        </tbody>\n      </table>\n      <h4>Substances interdites en compétition</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Exemples</th><th>Effet recherché</th></tr></thead>\n        <tbody>\n          <tr><td><strong>S6</strong> — Stimulants</td><td><span class=\"kw-ttt\">Amphétamines</span> ; <span class=\"kw-ttt\">cocaïne</span> ; cathinones ; <span class=\"kw-ttt\">méthylphénidate</span> ; <span class=\"kw-ttt\">modafinil</span></td><td><span class=\"kw-clinique\">↓ fatigue</span> ; ↑ attention et concentration ; amélioration des temps de réaction</td></tr>\n          <tr><td><strong>S7</strong> — Narcotiques</td><td>Analgésiques dérivés des <span class=\"kw-ttt\">opiacés</span> : <span class=\"kw-ttt\">morphine</span>, <span class=\"kw-ttt\">buprénorphine</span>, <span class=\"kw-ttt\">méthadone</span></td><td><span class=\"kw-clinique\">↓ sensation de douleur</span> ; effet sédatif ; effet euphorisant</td></tr>\n          <tr><td><strong>S8</strong> — Cannabinoïdes</td><td><span class=\"kw-ttt\">Cannabis</span> ; THC naturels ou synthétiques ; cannabinoïdes synthétiques — <strong>sauf CBD</strong></td><td>↑ relâchement musculaire ; <span class=\"kw-clinique\">↓ anxiété</span> ; amélioration du sommeil</td></tr>\n          <tr><td><strong>S9</strong> — Glucocorticoïdes</td><td><strong>Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">glucocorticoïdes</span></strong> par voie orale, IV, IM ou rectale</td><td>Effet psychostimulant ; <span class=\"kw-clinique\">↑ endurance</span> et tolérance à la douleur</td></tr>\n        </tbody>\n      </table>\n      <h4>Substances interdites dans certains sports</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Sports concernés</th><th>Effet recherché</th></tr></thead>\n        <tbody>\n          <tr><td><strong>P1</strong> — β-bloquants</td><td><strong>En compétition :</strong> automobile, billard, fléchettes, golf, ski, sports subaquatiques<br><strong>En et hors compétition :</strong> tir, tir à l'arc</td><td><span class=\"kw-clinique\">Anxiolyse</span> ; ↓ fréquence cardiaque ; ↓ tremblements</td></tr>\n        </tbody>\n      </table>\n      <h4>Méthodes interdites (en compétition et hors compétition)</h4>\n      <table >\n        <thead><tr><th>Méthode</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Manipulation de sang ou de composants sanguins</strong></td><td>Amélioration artificielle du transport ou de la libération de l'O₂ ; administration ou réintroduction de <span class=\"kw-bio\">sang</span> autologue, allogénique ou hétérologue, ou de <span class=\"kw-bio\">globules rouges</span> de toute origine</td></tr>\n          <tr><td><strong>Manipulations chimiques et physiques</strong></td><td>Substances ou procédés modifiant — ou risquant de modifier — l'<strong>intégrité et la validité des échantillons</strong> de contrôle : cathétérisation ; substitution ou altération des échantillons ; perfusions / injections IV</td></tr>\n          <tr><td><strong>Dopage <span class=\"kw-etio\">génétique</span></strong></td><td>Utilisation d'<span class=\"kw-bio\">acides nucléiques</span> modifiant <span class=\"kw-clinique\">les</span> séquences génomiques ou l'expression <span class=\"kw-etio\">génétique</span> ; utilisation de cellules normales ou <strong>génétiquement modifiées</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <strong><span class=\"kw-alerte\">caféine n'est PAS</span></strong> sur la liste des interdictions — c'est un <strong>distracteur fréquent en annale</strong>. De même, le <strong><span class=\"kw-ttt\">CBD est autorisé</span></strong> alors que <span class=\"kw-clinique\">les</span> autres cannabinoïdes sont interdits.</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Pour <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">β2-agonistes</span>, l'item « <span class=\"kw-alerte\">augmentation de la masse musculaire</span> » a déjà été <strong>compté vrai en annale</strong> — alors que leur effet principal est respiratoire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":1},{"id":"80-4","rang":"B","rubrique":"Définition","titre":"Connaître l’existence des diverses formes de dopage","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>formes de dopage</strong> se dégagent des définitions et de l'organisation de la liste des interdictions.</p>\n      <h4>Selon le moyen employé</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Dopage par substances</strong></td><td>Recours aux classes <span class=\"kw-ttt\">S0 à S9</span> et <span class=\"kw-ttt\">P1</span> de la liste des interdictions</td></tr>\n          <tr><td><strong>Dopage par méthodes</strong></td><td>Manipulation de sang (<span class=\"kw-def\">dopage sanguin</span>) ; manipulations chimiques et physiques des échantillons ; <span class=\"kw-def\">dopage génétique</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Selon la sphère concernée</h4>\n      <ul>\n        <li>la <strong><span class=\"kw-def\">conduite dopante</span></strong> dépasse le sport — elle peut viser des performances <strong>physiques, intellectuelles</strong> (ex. études, examens) <strong>ou artistiques</strong> ;</li>\n        <li>le <strong><span class=\"kw-def\">dopage</span></strong> au sens strict en est la <strong>forme sportive réglementée</strong>, dans le cadre des compétitions et manifestations fédérales.</li>\n      </ul>","frequence":0},{"id":"80-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence générale","contenu":"<p>D'après la fiche <span class=\"kw-def\">LiSA</span> item 80 : <strong>entre <span class=\"kw-chiffre\">5 et 10 %</span></strong> des <span class=\"kw-clinique\">contrôles antidopage</span> se révèlent <strong>positifs</strong>, avec des <strong>variations selon <span class=\"kw-clinique\">les</span> disciplines</strong> sportives.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Ce chiffre est une prévalence <strong>parmi <span class=\"kw-clinique\">les</span> sportifs contrôlés</strong> (dopage <em>détecté</em>), et non la prévalence réelle du dopage en population sportive — laquelle est vraisemblablement <span class=\"kw-alerte\">sous-estimée</span> puisque le passeport biologique et <span class=\"kw-clinique\">les</span> contrôles ne dépistent pas toutes <span class=\"kw-clinique\">les</span> situations.</div>","frequence":0},{"id":"80-6","rang":"B","rubrique":"Définition","titre":"Connaître les principes, règles, méthodes, et organisations de la lutte contre le dopage","contenu":"<h4><span class=\"kw-clinique\">Les</span> instances de la lutte contre le dopage</h4>\n      <p>La lutte contre le dopage repose sur la <strong>coordination</strong> de plusieurs acteurs.</p>\n      <table >\n        <thead><tr><th>Instance</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">AMA</span></strong> — Agence mondiale antidopage</td><td>Supervise <span class=\"kw-clinique\">les</span> activités antidopage dans le monde entier ; garante de la mise en place et du respect du <strong>Code mondial antidopage</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">AFLD</span></strong> — Agence française de lutte contre le dopage</td><td>Organise <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">contrôles antidopage</span> conformément au Code mondial et au standard international de l'AMA ; peut organiser des contrôles lors de compétitions internationales</td></tr>\n          <tr><td><strong>Fédérations sportives</strong></td><td>Partenaires de la coordination antidopage</td></tr>\n          <tr><td><strong><span class=\"kw-def\">AMPD</span></strong> — Antennes médicales de prévention et de lutte contre le dopage</td><td>Volet médical : prévention, <span class=\"kw-def\">suivi</span> et prise en charge des sportifs</td></tr>\n        </tbody>\n      </table>\n      <h4><span class=\"kw-clinique\">Les</span> méthodes de détection du dopage</h4>\n      <table >\n        <thead><tr><th>Stratégie</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mesure directe</strong></td><td><span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">contrôles antidopage</span>, mis en place par l'<span class=\"kw-def\">AFLD</span> — réalisés en compétition comme à l'entraînement</td></tr>\n          <tr><td><strong>Mesure indirecte</strong></td><td>Le <strong><span class=\"kw-def\">passeport biologique de l'athlète</span></strong>, <span class=\"kw-def\">suivi</span> dans le temps de <span class=\"kw-bio\">variables biologiques</span> :<br><strong>Module hématologique</strong> (matrice : <span class=\"kw-bio\">sang</span>) — méthodes d'amélioration du transport de l'O₂ ; transfusions et manipulations sanguines<br><strong>Module endocrinien</strong> (matrice : <span class=\"kw-bio\">urines</span>) — agents anabolisants<br><strong>3ᵉ module</strong> (hormone de croissance) — en cours d'élaboration</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Limite.</strong> Le <span class=\"kw-def\">passeport biologique</span> ne permet <strong>pas de dépister toutes <span class=\"kw-clinique\">les</span> situations de dopage</strong> : il met en évidence le dopage par ses <strong>effets sur l'organisme</strong>, pas par la prise elle-même.</div>\n      <h4>L'aspect législatif</h4>\n      <p>La <strong>France</strong> a été l'un des premiers pays à légiférer sur le dopage. La <strong><span class=\"kw-chiffre\">loi de 2006</span></strong> comporte deux volets :</p>\n      <ul>\n        <li><strong>Volet répressif</strong> — la <strong>liste des substances et procédés interdits</strong> ; il appartient à chaque athlète de s'assurer qu'aucun produit qu'il utilise ne contient de substance <span class=\"kw-ci\">interdite</span> ;</li>\n        <li><strong>Volet préventif</strong> — instauration d'un <strong><span class=\"kw-def\">suivi médical longitudinal</span></strong> des sportifs de haut niveau.</li>\n      </ul>","frequence":0},{"id":"80-7","rang":"B","rubrique":"Définition","titre":"Savoir à qui s’applique la règlementation anti-dopage","contenu":"<p>La <strong>règlementation anti-dopage</strong> s'applique à <strong>tout sportif</strong> dès lors qu'il participe à une <strong>compétition ou à une manifestation agréée par une fédération sportive</strong> :</p>\n      <ul>\n        <li>sportif <strong>licencié ou non licencié</strong> ;</li>\n        <li>sportif <strong>professionnel ou amateur</strong>.</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">contrôles</span> peuvent avoir lieu <strong>lors des compétitions</strong>, mais aussi <strong>au cours des entraînements</strong> préparatoires à ces compétitions ou manifestations.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le sportif <strong><span class=\"kw-alerte\">ne peut pas se soustraire au contrôle</span></strong> : un <strong>refus</strong> ou une <strong>abstention</strong> est <strong>sanctionné de la même façon</strong> que s'il était convaincu de dopage.</div>","frequence":0},{"id":"80-8","rang":"A","rubrique":"Prise en charge","titre":"Savoir rechercher le caractère dopant ou non d’une prescription médicale","contenu":"<p>Toute prescription médicale chez un sportif impose de <strong>vérifier le caractère dopant ou non</strong> du produit <strong>avant</strong> sa délivrance.</p>\n      <h4>Démarche concrète</h4>\n      <ul>\n        <li>se référer à la <strong>notice du médicament</strong> ;</li>\n        <li>consulter le <strong>moteur de recherche du site de l'<span class=\"kw-def\">AFLD</span></strong>, qui indique le statut (autorisé / <span class=\"kw-ci\">interdit</span>) de la molécule.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Avis spécialisé.</strong> <span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">AMPD</span></strong> (antennes médicales de prévention et de lutte contre le dopage) sont des <strong>centres ressources</strong> capables de donner un avis spécialisé et autorisé sur le caractère dopant d'une prescription et sur le <span class=\"kw-def\">suivi</span> médical des sportifs.</div>\n      <div class=\"callout callout-warn\"><strong>Exception thérapeutique (AUT).</strong> Si le sportif doit recevoir un traitement contenant une <span class=\"kw-ttt\">substance interdite</span> pour un <strong>problème de santé diagnostiqué</strong>, la procédure d'<strong><span class=\"kw-def\">autorisation d'usage à des fins thérapeutiques</span></strong> le permet.</div>\n      <div class=\"callout callout-danger\"><strong>Responsabilité.</strong> En vertu du volet répressif de la loi de 2006, c'est <strong>au sportif lui-même</strong> qu'il incombe de s'assurer qu'aucun produit utilisé ne contient de <span class=\"kw-ttt\">substance interdite</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":0},{"id":"80-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les risques liés au dopage et aux conduites dopantes","contenu":"<h4>Risque sanctionnel</h4>\n      <p>En cas de <span class=\"kw-clinique\">contrôle antidopage positif</span>, <span class=\"kw-clinique\">les</span> sanctions encourues sont de plusieurs ordres.</p>\n      <table >\n        <thead><tr><th>Type de sanction</th><th>Portée</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sanctions sportives</strong></td><td>De la simple <strong>suspension</strong> par la fédération (durée déterminée) jusqu'à la <strong><span class=\"kw-alerte\">radiation à vie</span></strong></td></tr>\n          <tr><td><strong>Sanctions pénales</strong></td><td>Possibles <strong>dans certains cas</strong></td></tr>\n          <tr><td><strong>Sanctions de l'entourage</strong></td><td>Peuvent concerner l'<strong>entourage ou <span class=\"kw-clinique\">les</span> soignants</strong> du sportif s'ils ont <span class=\"kw-alerte\">facilité l'usage</span> de produits dopants ou <span class=\"kw-alerte\">incité</span> à leur usage</td></tr>\n        </tbody>\n      </table>\n      <h4>Risque médical</h4>\n      <p>Le dopage expose à des <strong>conséquences médicales psychiatriques et non psychiatriques</strong>, <strong>variables selon le produit</strong> concerné et le niveau d'utilisation. C'est précisément cette variabilité qui justifie la <strong>coordination multidisciplinaire</strong> de la prise en charge (addictologie, psychiatrie, pharmacologie, hématologie, endocrinologie, médecine du sport) — cf. objectif sur la prévention.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> Le détail des complications <strong>par classe de produit</strong> (anabolisants, EPO, stimulants…) n'est <strong>pas sourçable</strong> ici : le chapitre item 80 du Collège de psychiatrie/addictologie (<em>PSYCHIATRIE.pdf</em>, p. 391-396) reste générique (« conséquences psychiatriques et non psychiatriques… variables en fonction du produit ») et ne fournit aucun tableau de risques par classe. Kevin complétera ce détail depuis une source spécifique, sans données inventées.</div>","frequence":0},{"id":"80-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes de la politique de prévention du dopage","contenu":"<h4><span class=\"kw-clinique\">Les</span> AMPD, pivot de la prévention</h4>\n      <p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">antennes médicales de prévention et de lutte contre le dopage (AMPD)</span></strong> sont implantées dans des structures hospitalières, rattachées aux <strong>unités de médecine du sport</strong> ou aux <strong>unités d'addictologie</strong>. Leurs missions de prévention :</p>\n      <ul>\n        <li><strong>consultations anonymes</strong>, ouvertes aux personnes ayant eu recours à des pratiques de dopage ;</li>\n        <li><strong>enseignement, information et prévention</strong> des pratiques dopantes ;</li>\n        <li><span class=\"kw-clinique\">recherche</span> autour des conduites dopantes ;</li>\n        <li><strong>recueil de données épidémiologiques</strong> et <strong>veille sanitaire</strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Numéro vert « Écoute et Dopage ».</strong> Ouvert aux <strong>sportifs, à leurs proches et à leurs encadrants</strong> — il aide et oriente <span class=\"kw-clinique\">les</span> personnes concernées par le dopage.</div>\n      <h4>Le <span class=\"kw-def\">suivi</span> médical longitudinal</h4>\n      <p>Volet préventif de la <strong><span class=\"kw-chiffre\">loi de 2006</span></strong> : instauration d'un <strong><span class=\"kw-def\">suivi</span> médical longitudinal</strong> des <strong>sportifs de haut niveau</strong>.</p>\n      <h4>Le rôle du médecin face à une suspicion</h4>\n      <p>Tout médecin amené à déceler des signes évoquant une pratique de dopage est tenu de :</p>\n      <ul>\n        <li><strong>refuser la délivrance</strong> du ou des certificats médicaux habituels ;</li>\n        <li><strong>informer le patient</strong> des risques encourus et lui proposer une <strong>orientation vers une AMPD</strong> ;</li>\n        <li><strong>transmettre <span class=\"kw-clinique\">les</span> données</strong> recueillies au médecin responsable de l'AMPD de sa région — le patient est informé de cette transmission, qui se fait dans le <strong>respect du secret médical</strong> et en <strong>préservant l'anonymat</strong> du sportif.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Des <strong><span class=\"kw-alerte\">sanctions disciplinaires</span></strong> sont prévues par la loi contre <span class=\"kw-clinique\">les</span> <strong>médecins qui n'auraient pas signalé un cas de dopage à l'AMPD</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 77 — Addiction aux psychotropes</em></p>","frequence":0}],"astuces":[],"strategie":{"hospit":"<p><strong>Cadre :</strong> prise en charge <span class=\"kw-def\">ambulatoire</span>, sans <span class=\"kw-alerte\">urgence</span> vitale propre au dopage.<br><strong>Orientation pivot :</strong> <span class=\"kw-def\">antenne médicale de prévention et de lutte contre le dopage (AMPD)</span>, implantée en structure hospitalière au sein des <span class=\"kw-def\">unités de médecine du sport</span> ou des <span class=\"kw-def\">unités d'addictologie</span>.<br><strong>Accès :</strong> <span class=\"kw-def\">consultations anonymes</span> ouvertes au sportif, à ses proches et à ses encadrants ; <span class=\"kw-def\">numéro vert « Écoute et Dopage »</span> pour aider et orienter.<br><strong>Obl<span class=\"kw-chiffre\">iga</span>tion :</strong> tout <span class=\"kw-alerte\">sportif positif à un contrôle antidopage</span> doit obligatoirement être <span class=\"kw-def\">suivi</span> par l'AMPD, qui délivre un <span class=\"kw-def\">certificat nominatif</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Contrôle antidopage positif</span> : sanctions sportives (de la suspension jusqu'à la <span class=\"kw-alerte\">radiation à vie</span>) et parfois <span class=\"kw-alerte\">sanctions pénales</span></li><li><span class=\"kw-alerte\">Refus ou abstention au contrôle</span> : le sportif ne peut s'y soustraire et est <span class=\"kw-alerte\">sanctionné de la même façon que s'il était convaincu de dopage</span></li><li>Sanctions pouvant <span class=\"kw-alerte\">concerner l'entourage ou les soignants</span> s'ils ont <span class=\"kw-alerte\">facilité l'usage</span> ou <span class=\"kw-alerte\">incité</span> au dopage</li><li>Médecin décelant des <span class=\"kw-alerte\">signes évoquant une pratique de dopage</span> : déclenche une obl<span class=\"kw-chiffre\">iga</span>tion médico-légale (refus de certificat, orientation et <span class=\"kw-def\">signalement</span> AMPD)</li><li><span class=\"kw-alerte\">Sanctions disciplinaires</span> prévues contre le médecin qui n'aurait pas signalé un cas de dopage à l'AMPD</li></ul>","principes":"<p><strong>Principe :</strong> prise en charge <span class=\"kw-def\">variable selon le produit</span>, ses conséquences médicales (psychiatriques et non psychiatriques) et le niveau d'utilisation ; articulée autour de l'évaluation du caractère dopant et de l'orientation vers l'AMPD.</p><p><strong>Évaluer le caractère dopant d'une prescription</strong></p><p>CAT : sportif + médicament <span class=\"kw-ci\">interdit</span> nécessaire à un soin → demande d'AUT avant prescription</p><ul><li>Rechercher le caractère dopant ou non en se référant à la <span class=\"kw-def\">notice du médicament</span> et au <span class=\"kw-def\">moteur de recherche du site AFLD</span></li><li><span class=\"kw-ci\">Substances interdites</span> classées en catégories <span class=\"kw-ttt\">S0 à S9</span> (en et/ou hors compétition) et <span class=\"kw-ttt\">P1 (β-bloquants)</span> dans certains sports, sur une liste de l'<span class=\"kw-def\">AMA mise à jour chaque année</span></li><li><span class=\"kw-def\">Autorisation d'usage à des fins thérapeutiques (AUT)</span> : permet à un sportif un traitement contenant une <span class=\"kw-ci\">substance interdite</span> pour un état pathologique diagnostiqué</li></ul><p><strong>Orientation & prise en charge spécialisée</strong></p><p>CAT : transmission obl<span class=\"kw-chiffre\">iga</span>toire des données au médecin responsable de l'AMPD, dans le respect du secret médical et de l'anonymat du sportif</p><ul><li>Adresser à une <span class=\"kw-def\">AMPD</span> pour avis spécialisé et <span class=\"kw-def\">suivi</span> médical</li><li><span class=\"kw-ttt\">Coordination multidisciplinaire</span> selon le produit : addictologie, psychiatrie, pharmacologie, hématologie, endocrinologie, médecine du sport</li><li>Tout médecin décelant des signes de dopage doit <span class=\"kw-alerte\">refuser la délivrance des certificats médicaux habituels</span>, informer le patient des risques et l'orienter vers une AMPD</li></ul><p><strong>Prévention & cadre légal</strong></p><ul><li><span class=\"kw-ttt\">Information et éducation</span> sur <span class=\"kw-clinique\">les</span> risques du dopage et des conduites dopantes</li><li><span class=\"kw-chiffre\">Loi de 2006</span>, volet préventif : <span class=\"kw-def\">suivi médical longitudinal</span> des sportifs de haut niveau</li><li><span class=\"kw-chiffre\">Loi de 2006</span>, volet répressif : liste de substances et procédés interdits ; il appartient à l'athlète de s'assurer qu'aucun produit utilisé ne contient de <span class=\"kw-ci\">substance interdite</span></li></ul>","suivi":"<p><strong>Sportif sanctionné :</strong> <span class=\"kw-alerte\">suivi obligatoire par l'AMPD</span> ; le médecin responsable délivre un <span class=\"kw-def\">certificat nominatif</span> témoignant de la démarche de prise en charge.<br><strong>Haut niveau :</strong> <span class=\"kw-def\">suivi médical longitudinal</span> instauré par la <span class=\"kw-chiffre\">loi de 2006</span>.<br><strong>Détection indirecte :</strong> <span class=\"kw-def\">passeport biologique de l'athlète</span> = <span class=\"kw-def\">suivi</span> dans le temps de <span class=\"kw-bio\">variables biologiques</span> (module <span class=\"kw-bio\">hématologique</span> sur sang, module <span class=\"kw-bio\">endocrinien</span> sur urines) pour dépister EPO, transfusions et anabolisants.<br><strong>Limite :</strong> le passeport <span class=\"kw-ttt\">biologique</span> ne permet pas de dépister toutes <span class=\"kw-clinique\">les</span> situations de dopage.</p>"},"liensGlobaux":[{"href":"https://www.afld.fr/","label":"AFLD — Agence Française de Lutte contre le Dopage"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Sportif vu en consultation médicale — compétition ou manifestation sous fédération sportive","detail":"<h4>CAT — Conduite du médecin face à un sportif — Prescription, suspicion de dopage et contrôle positif</h4>","branches":[{"to":"q-caractere","label":"Prescription à rédiger","color":"blue"},{"to":"t-suspicion","label":"Signes évoquant une pratique de dopage","color":"red"},{"to":"t-controle","label":"Contrôle antidopage positif","color":"red"}]},{"id":"q-caractere","kind":"decision","label":"Substance à prescrire inscrite sur la liste des interdictions ? — vérifier la notice du médicament + le moteur de recherche du site AFLD","branches":[{"to":"t-libre","label":"Non (substance autorisée)","color":"green"},{"to":"q-patho","label":"Oui (substance interdite)","color":"amber"}]},{"id":"t-libre","kind":"terminal","label":"Prescription possible","color":"green","detail":"<h4>Conduite</h4><ul><li>Prescription standard possible : la substance n'est pas une <span class=\"kw-ci\">substance interdite</span></li><li>Revérifier à chaque renouvellement, la <span class=\"kw-def\">liste de l'AMA étant mise à jour chaque année</span></li></ul>"},{"id":"q-patho","kind":"decision","label":"Un état pathologique diagnostiqué justifie-t-il ce traitement ?","branches":[{"to":"t-aut","label":"Oui","color":"amber"},{"to":"t-eviction","label":"Non","color":"amber"}]},{"id":"t-aut","kind":"terminal","label":"Demande d'AUT avant prescription","color":"amber","detail":"<h4>Conduite</h4><ul><li>Engager une <span class=\"kw-def\">autorisation d'usage à des fins thérapeutiques (AUT)</span></li><li>Permet l'usage d'une <span class=\"kw-ci\">substance interdite</span> à visée de soin, pour un problème de santé aigu ou chronique diagnostiqué</li></ul>"},{"id":"t-eviction","kind":"terminal","label":"Ne pas prescrire la substance interdite","color":"amber","detail":"<h4>Conduite</h4><ul><li>Ne pas prescrire la <span class=\"kw-ci\">substance interdite</span> en dehors d'une procédure d'AUT</li><li>Rappeler qu'il appartient à l'athlète de s'assurer qu'aucun médicament ou supplément utilisé ne contient de <span class=\"kw-ci\">substance interdite</span></li></ul>"},{"id":"t-suspicion","kind":"terminal","label":"Signes de dopage décelés : obligations médico-légales","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Refuser la délivrance</span> du ou des certificats médicaux habituels</li><li>Informer le patient des <span class=\"kw-alerte\">risques encourus</span> et lui proposer une orientation vers une <span class=\"kw-def\">AMPD</span> pour recevoir <span class=\"kw-clinique\">les</span> soins nécessaires</li><li><span class=\"kw-alerte\">Transmettre obligatoirement</span> <span class=\"kw-clinique\">les</span> données recueillies au médecin responsable de l'AMPD de sa région</li></ul><h4>Cadre</h4><ul><li>Transmission dans le <span class=\"kw-def\">respect du secret médical</span> et en préservant l'<span class=\"kw-def\">anonymat du sportif</span> (patient informé de la transmission)</li><li><span class=\"kw-alerte\">Sanctions disciplinaires</span> prévues contre le médecin qui n'aurait pas signalé le cas à l'AMPD</li></ul>"},{"id":"t-controle","kind":"terminal","label":"Contrôle antidopage positif","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Suivi obligatoire par l'AMPD</span> ; le médecin responsable délivre un <span class=\"kw-def\">certificat nominatif</span> attestant la démarche de prise en charge</li><li><span class=\"kw-ttt\">Coordination multidisciplinaire</span> selon le produit (addictologie, psychiatrie, pharmacologie, hématologie, endocrinologie, médecine du sport)</li></ul><h4>Sanctions</h4><ul><li><span class=\"kw-alerte\">Sanctions sportives</span> : de la suspension jusqu'à la <span class=\"kw-alerte\">radiation à vie</span></li><li><span class=\"kw-alerte\">Sanctions pénales</span> dans certains cas, pouvant aussi concerner l'entourage ou <span class=\"kw-clinique\">les</span> soignants ayant <span class=\"kw-alerte\">facilité l'usage</span> ou <span class=\"kw-alerte\">incité</span> au dopage</li></ul>"}]},"cards":[]};